(() => {
'use strict';
const clean=v=>v!==undefined&&v!==null&&v!==''&&!['Not specified','Not supplied','To verify'].includes(v);
const fields={style:['style','Style'],room:['room','Room'],movement:['movement','Movement'],numeral:['numeralType','Numeral Type','Dial'],features:['features','Features']};
const colours=['Black','White','Cream','Beige','Brown','Grey','Green','Blue','Pink','Red','Orange','Yellow','Gold','Silver','Bronze','Natural','Multi-colour'];
const stock={'In stock':'In Stock','In Stock':'In Stock',Incoming:'Due Soon / Incoming','Coming soon':'Due Soon / Incoming','Due Soon':'Due Soon / Incoming','Due Soon / Incoming':'Due Soon / Incoming','Pre-order':'Pre-order'};
function values(p,k){let v=(fields[k]||[k]).map(f=>p[f]).find(clean);if(k==='type')v=p.size==='Oversized'?[p.type,'Oversized Clocks']:p.type;return (Array.isArray(v)?v:[v]).filter(clean).map(x=>{if(k==='availability')return stock[x];if(k==='movement'){if(/^Audible Ticking/.test(x))return 'Audible Ticking';if(x==='Silent Sweep')return 'Silent / Sweep';}if(k==='material')return ({Plastic:'Plastic / Composite',Composite:'Plastic / Composite',Stone:'Stone / Concrete',Concrete:'Stone / Concrete'})[x]||x;return x;}).filter(clean).filter(x=>k!=='colour'||colours.includes(x)).filter(x=>k!=='size'||['Small','Medium','Large','Oversized'].includes(x)).filter(x=>k!=='features'||['Silent Movement','Pendulum','Indoor / Outdoor','Battery Operated'].includes(x));}
function numeric(p,k){const keys=k==='price'?['tradePrice','Trade Price']:['widthMm','width_mm','Width (mm)','diameterMm','diameter_mm','Diameter (mm)'];const v=keys.map(f=>p[f]).find(clean);return typeof v!=='boolean'&&v!==undefined&&Number.isFinite(Number(v))&&Number(v)>=0?Number(v):null;}
function configure(products){const has=k=>products.some(p=>values(p,k).length);const labels={type:'Product Type',width:'Size / Width',size:'Size Band',colour:'Colour',style:'Style',availability:'Availability'};if(has('material'))labels.material='Material';if(has('room'))labels.room='Room';if(products.length&&products.filter(p=>values(p,'movement').length).length/products.length>=.8)labels.movement='Movement';if(has('numeral'))labels.numeral='Numeral Type';if(has('features'))labels.features='Features';labels.price='Price';return {labels,facetOptions:{},numericFacets:['width','price'],initialOpen:['width'],clocks:true,facetNotes:{availability:'Gallery availability has not been verified.'},filterNote:'Width / diameter uses supplied millimetres. Existing Thomas Kent size bands are retained. Verify Gallery availability before ordering.'};}
window.ClocksFilters={configure,values,numeric};
})();
